name: PR Preview Deployment

on:
  pull_request:
    paths:
      - "website/**"
  workflow_dispatch:

permissions:
  contents: read
  pull-requests: write
  pages: write
  id-token: write

jobs:
  preview:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: npm
          cache-dependency-path: website/package-lock.json

      - name: Install dependencies
        run: npm ci
        working-directory: website

      - name: Build website
        env:
          VITE_BASE: /
        run: npm run build
        working-directory: website

      - name: Upload artifact
        uses: actions/upload-artifact@v4
        with:
          name: preview-site
          path: website/dist
          retention-days: 30

      - name: Deploy to Cloudflare Pages
        if: ${{ secrets.CLOUDFLARE_API_TOKEN && secrets.CLOUDFLARE_ACCOUNT_ID }}
        uses: cloudflare/wrangler-action@v3
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          workingDirectory: website
          command: pages deploy dist --project-name=razorconsole-preview --branch=pr-${{ github.event.pull_request.number }}

      - name: Post PR comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.issue.number;
            const artifactName = 'preview-site';
            const artifactUrl = `https://github.com/${owner}/${repo}/actions/runs/${context.runId}/artifacts/${artifactName}`;
            const cloudflareUrl = `${{ github.event.workflow_run.html_url }}`;
            const commentBody = `## 🚀 Preview Deployment

[Download artifact](${artifactUrl}) (30-day retention)

${{ secrets.CLOUDFLARE_API_TOKEN && secrets.CLOUDFLARE_ACCOUNT_ID ? `[Live preview](${cloudflareUrl})` : '' }}

This preview includes all website changes from this pull request.`;

            // Find existing comment
            const comments = await github.rest.issues.listComments({
              owner,
              repo,
              issue_number: prNumber
            });

            const previewComment = comments.data.find(comment => 
              comment.body.includes('## 🚀 Preview Deployment')
            );

            if (previewComment) {
              // Update existing comment
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: previewComment.id,
                body: commentBody
              });
            } else {
              // Create new comment
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: prNumber,
                body: commentBody
              });
            }
